  // Resources page
  'resources.all': { en: 'All', kn: 'ಎಲ್ಲಾ', hi: 'सभी', te: 'అన్నీ' },
  'resources.res1.desc': { en: 'For traffic-related complaints, accident reports, and challan inquiries.', kn: 'ಸಂಚಾರ ಸಂಬಂಧಿತ ದೂರುಗಳು, ಅಪಘಾತ ವರದಿಗಳು ಮತ್ತು ಚಲನ್ ವಿಚಾರಣೆಗಳಿಗೆ.', hi: 'ट्रैफ़िक संबंधित शिकायतें, दुर्घटना रिपोर्ट और चालान जाँच के लिए।', te: 'ట్రాఫిక్ సంబంధిత ఫిర్యాదులు, ప్రమాద నివేదికలు మరియు చలాన్ విచారణల కోసం.' },
  'resources.res2.desc': { en: 'For civic issues: potholes, garbage, streetlights, drainage, road damage.', kn: 'ನಾಗರಿಕ ಸಮಸ್ಯೆಗಳಿಗೆ: ಗುಂಡಿಗಳು, ತ್ಯಾಜ್ಯ, ಬೀದಿ ದೀಪಗಳು, ಒಳಚರಂಡಿ, ರಸ್ತೆ ಹಾನಿ.', hi: 'नागरिक समस्याओं के लिए: गड्ढे, कचरा, स्ट्रीटलाइट, नाली, सड़क क्षति।', te: 'పౌర సమస్యల కోసం: గుంతలు, చెత్త, వీధి దీపాలు, మురుగు, రోడ్డు దెబ్బ.' },
  'resources.res3.desc': { en: 'For power outages, electricity complaints, and new connections.', kn: 'ವಿದ್ಯುತ್ ವ್ಯತ್ಯಯ, ವಿದ್ಯುತ್ ದೂರುಗಳು ಮತ್ತು ಹೊಸ ಸಂಪರ್ಕಗಳಿಗೆ.', hi: 'बिजली कटौती, बिजली शिकायतों और नए कनेक्शन के लिए।', te: 'విద్యుత్ అంతరాయం, విద్యుత్ ఫిర్యాదులు మరియు కొత్త కనెక్షన్ల కోసం.' },
  'resources.res4.desc': { en: 'For public safety concerns, harassment, and criminal matters.', kn: 'ಸಾರ್ವಜನಿಕ ಸುರಕ್ಷತೆ, ಕಿರುಕುಳ ಮತ್ತು ಅಪರಾಧ ವಿಷಯಗಳಿಗೆ.', hi: 'सार्वजनिक सुरक्षा, उत्पीड़न और आपराधिक मामलों के लिए।', te: 'ప్రజా భద్రత, వేధింపులు మరియు నేర విషయాల కోసం.' },
  'resources.res5.desc': { en: 'For reporting cybercrime, online fraud, and digital scams.', kn: 'ಸೈಬರ್ ಅಪರಾಧ, ಆನ್‌ಲೈನ್ ವಂಚನೆ ಮತ್ತು ಡಿಜಿಟಲ್ ವಂಚನೆ ವರದಿಗಳಿಗೆ.', hi: 'साइबर अपराध, ऑनलाइन धोखाधड़ी और डिजिटल घोटालों की रिपोर्ट के लिए।', te: 'సైబర్ నేరాలు, ఆన్‌లైన్ మోసం మరియు డిజిటల్ స్కామ్‌ల నివేదిక కోసం.' },
  'resources.res6.desc': { en: 'General citizen assistance and government service complaints.', kn: 'ಸಾಮಾನ್ಯ ನಾಗರಿಕ ಸಹಾಯ ಮತ್ತು ಸರ್ಕಾರಿ ಸೇವಾ ದೂರುಗಳು.', hi: 'सामान्य नागरिक सहायता और सरकारी सेवा शिकायतें।', te: 'సాధారణ పౌర సహాయం మరియు ప్రభుత్వ సేవా ఫిర్యాదులు.' },
  'resources.res7.desc': { en: 'Free legal aid and tenant/landlord dispute guidance.', kn: 'ಉಚಿತ ಕಾನೂನು ಸಹಾಯ ಮತ್ತು ಬಾಡಿಗೆದಾರ-ಮಾಲೀಕ ವಿವಾದ ಮಾರ್ಗದರ್ಶನ.', hi: 'मुफ़्त कानूनी सहायता और किरायेदार-मालिक विवाद मार्गदर्शन।', te: 'ఉచిత న్యాయ సహాయం మరియు అద్దెదారు-యజమాని వివాద మార్గదర్శన.' },

